mapper.select:
SELECT a.id, a.student_id, a.type, a.head, a.content, a.release_date_time, a.updated_date_time, s.name AS name, f.file_url AS avatar FROM article a LEFT JOIN it_student s ON s.student_id = a.student_id AND s.deleted = 0 LEFT JOIN student_file f ON f.id = s.avatar_id
WHERE a.type = #{type}
ORDER BY a.updated_date_time DESC, a.id DESC LIMIT #{offset}, #{size}

SELECT COUNT(*)
FROM article
WHERE updated_date_time > #{updatedDateTime}

SELECT student_id, COUNT(*) AS total FROM article WHERE student_id IN
#{studentId}
GROUP BY student_id
